  const protectedAt = stmts.findIndex(protectedPred)
  assert.ok(gateAt > -1 && protectedAt > -1 && gateAt < protectedAt,
    `${why}（门在第 ${gateAt} 条语句，受保护副作用在第 ${protectedAt} 条；门挪到后面/副作用插到门前等于没守卫）`)
