    const summary = (n) => `${dayKey} 12:16:0${n} total=${n} dedup=0 filtered=0 truncated=0 pushed=${n} failed=0 elapsed=10.1s cachesaved=1`
    fs.writeFileSync(path.join(dir, 'run.log'), [summary(1), summary(2), summary(3)].join('\n') + '\n')
