        assert.strictEqual(hit.text, '', `${c.name} 304 不得带 body`)
        assert.strictEqual(hit.headers.etag, tag, `${c.name} 304 必须回显 ETag`)
        assert.strictEqual(hit.headers['cache-control'], 'no-store', `${c.name} 304 仍须 no-store`)
