  await aok('自动运行分时段：校验 / 窗口命中 / 跨午夜 / 边界唤醒（v3.401）', () => {
    const { parseAutoHHMM, normalizeAutoSchedule, autoIntervalAt } = require('./scripts/console.js')
    assert.strictEqual(parseAutoHHMM('00:00'), 0)
    assert.strictEqual(parseAutoHHMM('23:59'), 1439)
    assert.strictEqual(parseAutoHHMM('3:00'), null, '必须两位小时')
    assert.strictEqual(parseAutoHHMM('24:00'), null)
    assert.strictEqual(parseAutoHHMM('03:60'), null)

    const bad = [
      ['not-array', { }],
      ['too-many', Array.from({ length: 9 }, () => ({ start: '01:00', end: '02:00', interval: 10 }))],
      ['bad-start', [{ start: '3:00', end: '07:00', interval: 10 }]],
      ['same', [{ start: '03:00', end: '03:00', interval: 10 }]],
      ['iv-low', [{ start: '03:00', end: '07:00', interval: 2 }]],
      ['iv-high', [{ start: '03:00', end: '07:00', interval: 601 }]],
      ['iv-str', [{ start: '03:00', end: '07:00', interval: '10' }]]
    ]
    for (const [name, list] of bad) {
      const r = normalizeAutoSchedule(Array.isArray(list) ? list : name)
      assert.strictEqual(r.ok, false, `${name} 必须拒绝`)
    }
    const okv = normalizeAutoSchedule([{ start: '03:00', end: '07:00', interval: 60 }])
    assert.strictEqual(okv.ok, true)
    assert.deepStrictEqual({ start: okv.value[0].start, end: okv.value[0].end, interval: okv.value[0].interval },
      { start: '03:00', end: '07:00', interval: 60 })

    const bj = (h, m) => Date.UTC(2026, 10, 4, h - 8, m) // 北京时间 → UTC 毫秒
    const sched = normalizeAutoSchedule([{ start: '03:00', end: '07:00', interval: 60 }]).value
    assert.strictEqual(autoIntervalAt(sched, 5, bj(2, 59)).interval, 5, '窗口外走主间隔')
    assert.strictEqual(autoIntervalAt(sched, 5, bj(3, 0)).interval, 60, '窗口起点含')
    assert.strictEqual(autoIntervalAt(sched, 5, bj(6, 59)).interval, 60)
    assert.strictEqual(autoIntervalAt(sched, 5, bj(7, 0)).interval, 5, '窗口终点不含')
    const at3 = autoIntervalAt(sched, 5, bj(3, 30))
    // 边界必须扣掉当前分钟内的秒/毫秒，否则会晚醒（Sourcery Medium：04:30:45.123 → 距 07:00 应 ≈ 2:29:14.877）
    const at3s = autoIntervalAt(sched, 5, bj(3, 30) + 45 * 1000 + 123)
    assert.ok(Math.abs(at3s.untilChangeMs - (3.5 * 3600 * 1000 - 45 * 1000 - 123)) < 1000,
      `边界要扣掉秒/毫秒，实际 ${at3s.untilChangeMs}`)
    assert.ok(at3.untilChangeMs > 0 && at3.untilChangeMs <= 3.5 * 3600 * 1000, '必须给出到 07:00 的边界')

    // 跨午夜 23:00–07:00：23:30 与 06:59 都在窗口内
    const cross = normalizeAutoSchedule([{ start: '23:00', end: '07:00', interval: 120 }]).value
    assert.strictEqual(autoIntervalAt(cross, 5, bj(23, 30)).interval, 120)
    assert.strictEqual(autoIntervalAt(cross, 5, bj(6, 59)).interval, 120)
    assert.strictEqual(autoIntervalAt(cross, 5, bj(12, 0)).interval, 5)

    // 多条窗口：后命中的覆盖前者（按顺序取最后一个命中，便于临时覆盖）
    const multi = normalizeAutoSchedule([
      { start: '09:00', end: '12:00', interval: 8 },
      { start: '10:00', end: '11:00', interval: 3 }
    ]).value
    assert.strictEqual(autoIntervalAt(multi, 5, bj(9, 30)).interval, 8)
    assert.strictEqual(autoIntervalAt(multi, 5, bj(10, 30)).interval, 3, '重叠窗口后者优先')

    // 被后一条窗口遮住的边界不算「生效间隔变化」，不得唤醒白跑一轮（Sourcery Medium）
    const masked = normalizeAutoSchedule([
      { start: '03:00', end: '09:00', interval: 60 },
      { start: '03:00', end: '07:00', interval: 60 }
    ]).value
    // 06:00 时 07:00 边界不改变间隔（两条都是 60）⇒ 下一个真正的变化点是 09:00
    assert.strictEqual(autoIntervalAt(masked, 5, bj(6, 0)).untilChangeMs, 3 * 3600 * 1000)
  })

  await aok('HTTP: POST /api/notify-test 鉴权面（K2）', async () => {
    const { server } = createConsole({ token: TOKEN, stateDir: tmpDir() })
    const port = await listen(server)
    const noAuth = await request(port, 'POST', '/api/notify-test', { body: '' })
    assert.strictEqual(noAuth.status, 401, '无凭证 401')
    const badAuth = await request(port, 'POST', '/api/notify-test', { token: 'y'.repeat(32), body: '' })
    assert.strictEqual(badAuth.status, 401, '错 token 401')
    const csrf = await request(port, 'POST', '/api/notify-test', { headers: { cookie: `xbk_session=${TOKEN}` }, body: '' })
    assert.strictEqual(csrf.status, 401, 'POST 仅凭 Cookie 401（CSRF 面）')
  })
  // backlog b3 / C2-002：四个改状态端点（备份导入 / 手动触发 / 通知自检 / 停止任务）此前只靠全局
  // authorize()，与过滤写端点的「写面仅 Bearer」不一致。这里把「URL 凭证不得用于写」钉在行为上：
  // 400 query_token_not_allowed，且拒绝必须发生在 readBody / 取锁 / spawn 之前（无任何副作用）；
  // 同一端点用 Bearer 仍照常进业务层。A1 起查询串 token 已不是任何端点的凭证，这个专属 400
  // 是留给旧客户端的明确指引（而不是含糊 401），行为本身不放宽。
  await aok('HTTP: 改状态端点拒绝 URL query token（C2-002）', async () => {
    const dir = tmpDir()
    const { server, runs } = createConsole({ token: TOKEN, stateDir: dir })
    const port = await listen(server)
    // runs 是模块级 Map（跨实例共享），只能比增量——断言「本次没有新记录」。
    const runsBefore = runs.size
    const lastAcceptFile = path.join(dir, 'console-lastaccept.json')
    const viaQueryUrl = '?token=' + encodeURIComponent(TOKEN)
    // 四条端点各配一个「鉴权之后必然确定的」分支：导入=坏 JSON、触发=非法动作、取消=不存在的 id、
    // 自检=重放窗（预置 30s 帧），都不 spawn 真实子进程、不落盘。
    const endpoints = [
      ['/api/backup/import', '{}'],
      ['/trigger', 'action=check'],
      ['/api/notify-test', ''],
      ['/api/runs/cancel', 'id=1700000000000.1']
    ]
    try {
      for (const [endpoint, body] of endpoints) {
        const viaQuery = await request(port, 'POST', endpoint + viaQueryUrl, { body })
        assert.strictEqual(viaQuery.status, 400, `${endpoint} 带 ?token= 必须 400`)
        assert.strictEqual(JSON.parse(viaQuery.text).code, 'query_token_not_allowed', `${endpoint} 错误码`)
        // 即使同时带合法 Bearer 也拒绝：URL 里的凭证不得被当成可用写法（与过滤写端点同口径）。
        const both = await request(port, 'POST', endpoint + viaQueryUrl, { token: TOKEN, body })
        assert.strictEqual(both.status, 400, `${endpoint} ?token= + Bearer 仍必须 400`)
        assert.strictEqual(JSON.parse(both.text).code, 'query_token_not_allowed')
        // 仅 Cookie：写面不收 Cookie（CSRF 面），错误码要具体到 cookie_not_allowed。
        const cookieOnly = await request(port, 'POST', endpoint, {
          body,
          headers: { cookie: `xbk_session=${TOKEN}` }
        })
        assert.strictEqual(cookieOnly.status, 401, `${endpoint} 仅 Cookie 必须 401`)
        assert.strictEqual(JSON.parse(cookieOnly.text).code, 'cookie_not_allowed')
      }
      // 拒绝发生在副作用之前：没有运行记录（不 spawn）、没有触发锁、没有重放帧。
      assert.strictEqual(runs.size, runsBefore, '被拒请求不得创建运行记录')
      // 用一次 readdir 快照断言「一个文件都没留下」，代替 `existsSync(lockFile)` /
      // `existsSync(lastAcceptFile)`：本用例随后就要按同一路径写重放帧（下面那行 writeFileSync），
      // 「先判存在、再按同一路径写」正是 js/file-system-race（CodeQL 121）的 check-then-use 形状，
      // 而报告方判的其实是「检查看到的」与「实际写到的」可能不是同一个对象。快照同时更强：
      // 触发锁、重放帧之外任何意料外的落盘都算失败。
      assert.deepStrictEqual(fs.readdirSync(dir), [], '被拒请求不得在 stateDir 留下任何文件（触发锁 / 重放帧 / 运行记录）')
      // 反向：Bearer 照常通过鉴权（各自走到鉴权之后的确定性分支，不 spawn）。
      const importBadJson = await request(port, 'POST', '/api/backup/import', {
        token: TOKEN,
        headers: { 'content-type': 'application/json' },
        body: '{not-json'
      })
      assert.strictEqual(importBadJson.status, 400, 'Bearer 应已过鉴权（导入坏 JSON 400）')
      assert.strictEqual(JSON.parse(importBadJson.text).code, 'invalid_json')
      const triggerBadAction = await request(port, 'POST', '/trigger', { token: TOKEN, body: 'action=hack' })
      assert.strictEqual(triggerBadAction.status, 400, 'Bearer 应已过鉴权（非法动作 400）')
      assert.strictEqual(JSON.parse(triggerBadAction.text).error, '未知 action')
      const cancelMissing = await request(port, 'POST', '/api/runs/cancel', { token: TOKEN, body: 'id=1700000000000.1' })
      assert.strictEqual(cancelMissing.status, 404, 'Bearer 应已过鉴权（不存在的 id 404）')
      fs.writeFileSync(lastAcceptFile, JSON.stringify({ 'notify-test': { at: Date.now() - REPLAY_WINDOW_MS / 2, runId: '1700000000000.7' } }))
      const notifyReplay = await request(port, 'POST', '/api/notify-test', { token: TOKEN, body: '' })
      assert.strictEqual(notifyReplay.status, 409, 'Bearer 应已过鉴权（60s 窗内重放 409）')
      assert.strictEqual(JSON.parse(notifyReplay.text).replayBlocked, true)
      // 只读端点不能跟着被砍成「无凭证」：GET 仍接受 Bearer / 会话 Cookie。
      const readViaBearer = await request(port, 'GET', '/api/runs', { token: TOKEN })
      assert.strictEqual(readViaBearer.status, 200, '只读端点仍接受 Bearer')
      // A1：查询串 token 不再是凭证——读端点带它一律 401（旧链接不能读数据）。
      const readViaQuery = await request(port, 'GET', '/api/runs' + viaQueryUrl)
      assert.strictEqual(readViaQuery.status, 401, '只读端点不再接受 ?token=')
    } finally {
      await new Promise((resolve) => server.close(resolve))
      fs.rmSync(dir, { recursive: true, force: true })
    }
  })
  await aok('HTTP: notify-test 60s 独立重放窗行为区分（K3）', async () => {
    // 两个独立实例（独立 stateDir）：lastAccept 是「内存 Map + 实时读盘合并（at 更大者胜）」，
    // 同一实例内先写 30s 帧再改盘为 61s 帧不会生效（内存 30s 帧更权威）。
    // 场景①：30s 前（60s 窗内）→ 409 + replayBlocked + runId 回带
    {
      const dir = tmpDir()
      const { server } = createConsole({ token: TOKEN, stateDir: dir })
      const port = await listen(server)
      fs.writeFileSync(path.join(dir, 'console-lastaccept.json'), JSON.stringify({ 'notify-test': { at: Date.now() - REPLAY_WINDOW_MS / 2, runId: '1750000000000.7' } }))
      const blocked = await request(port, 'POST', '/api/notify-test', { token: TOKEN, body: '' })
      assert.strictEqual(blocked.status, 409, '60s 窗内重放必须 409')
      const blockedBody = JSON.parse(blocked.text)
      assert.strictEqual(blockedBody.replayBlocked, true, '标记重放拦截')
      assert.strictEqual(blockedBody.runId, '1750000000000.7', '409 回带首轮 runId')
      // D2-S16：文案必须说「N 秒后可重试」且带 retryAfterS——旧文案谎称「已有任务在运行」
      assert.match(String(blockedBody.error || ''), /\d+ 秒后可重试/, '409 必须给出可重试倒计时')
      assert.ok(Number.isInteger(blockedBody.retryAfterS) && blockedBody.retryAfterS > 0 && blockedBody.retryAfterS <= 60, 'retryAfterS 在窗内')
      server.close()
    }
    // 场景②：61s 前（超 60s 窗；若误用 12min 全局窗此请求会被重放窗拦——60s 窗的区分性断言）
    // → 应越过重放窗、撞上既有锁（手工预占锁）→ 409 无 replayBlocked。
    // 不走 202+spawn：node xbk_function_v3.js --notify-test 直跑会真实推送（本机有真实凭证）。
    {
      const dir = tmpDir()
      const { server } = createConsole({ token: TOKEN, stateDir: dir })
      const port = await listen(server)
      fs.writeFileSync(path.join(dir, 'console-lastaccept.json'), JSON.stringify({ 'notify-test': { at: Date.now() - (REPLAY_WINDOW_MS + 1000), runId: '1750000000000.7' } }))
      assert.strictEqual(acquireLock(dir, Date.now(), 'other-token'), true, '预占锁成功')
      const lockConflict = await request(port, 'POST', '/api/notify-test', { token: TOKEN, body: '' })
      assert.strictEqual(lockConflict.status, 409, '越窗后撞锁仍 409')
      const lockBody = JSON.parse(lockConflict.text)
      assert.strictEqual(lockBody.replayBlocked, undefined, '锁冲突不带 replayBlocked（区别于重放窗 409）')
      server.close()
    }
  })
  // ── v3.340 控制台设置：拆成 5 组用例 ──────────────────────────────────────────
  // 旧版把 60+ 条断言挤在一个 aok 里：首错即中止，后面的断言与清理全部跳过（回潮实验实测
  // 只报 1 条失败、且进程被泄漏的监听句柄钉住）。现在每组自带 stateDir/server，退出时关服务
